import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');

  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);

  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');

  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');

  const [allUsers, setAllUsers] = useState([]);

  // AI Chat
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your NM Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    if (pageName === 'instructors') return 'users?role=instructor'; // NEW for admin
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    if (pageName === 'instructors') return { name: '', email: '', role: 'instructor' }; // NEW
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);
    setAllUsers([]);
    setShowChat(false);
    setChatMessages([{ sender: 'bot', text: "Hello! I'm your NM Portal assistant. Ask me anything about how to use the portal!" }]);
  };

  const load = async (endpoint) => {
    if (!endpoint) return [];
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: Array.isArray(course.students) ? course.students.map(Number) : []
        }));
        setCourses(fetched);
      }

      if (endpoint === 'submissions' && user?.role === 'instructor') {
        const usersRes = await axios.get(`${API}/users`);
        setAllUsers(usersRes.data);
      }

      return fetched;
    } catch (err) {
      console.error(err);
      return [];
    } finally {
      setLoading(false);
    }
  };

  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);

    const endpoint = getEndpoint(newPage);
    if (endpoint) {
      let fetched = await load(endpoint);
      setData(fetched);

      if (user?.role === 'student') {
        if (newPage === 'assignments' || newPage === 'announcements') {
          const filtered = fetched.filter(item => enrolledCourseIds.includes(item.courseid));
          setData(filtered);
        }
      }
    }
  };

  useEffect(() => {
    if (user) {
      load('courses').then(fetchedCourses => {
        const enrolledIds = fetchedCourses
          .filter(c => (c.students || []).includes(user.id))
          .map(c => c.id);
        setEnrolledCourseIds(enrolledIds);
      });
      goTo('courses');
    }
  }, [user]);

  useEffect(() => {
    if (user && page !== 'login' && page !== 'courses') {
      goTo(page);
    }
  }, [page, user]);

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => [...prev, courseId]);
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  const submitAssignment = async (assignmentId) => {
    if (!submissionText.trim()) {
      alert('Please write your answer before submitting.');
      return;
    }
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: submissionText
      });
      alert('Assignment submitted successfully!');
      setSubmissionText('');
      setSelectedAssignment(null);
      if (page === 'submissions') goTo('submissions');
    } catch (err) {
      alert('Submission failed');
    }
  };

  const viewSubmission = (text, submissionId) => {
    if (text && text.trim()) {
      setCurrentSubmissionText(text.trim());
      setCurrentSubmissionId(submissionId);
      setShowFileModal(true);
    } else {
      alert('No submission yet.');
    }
  };

  const requestDeleteSubmission = (submissionId) => {
    setItemToDelete(submissionId);
    setDeleteBase('submissions');
    setShowConfirmDelete(true);
  };

  const gradeSubmission = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const saveGrade = async () => {
    if (!gradeValue || isNaN(gradeValue) || parseInt(gradeValue) < 0 || parseInt(gradeValue) > 100) {
      alert('Please enter a valid grade (0-100)');
      return;
    }
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: parseInt(gradeValue),
        feedback: feedbackText
      });
      alert('Grade saved successfully!');
      setShowGradeModal(false);
      setGradeValue('');
      setFeedbackText('');
      setSubmissionToGrade(null);
      await goTo('submissions');
    } catch (err) {
      alert('Failed to save grade');
    }
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete}`);
      alert('Deleted successfully');
      setShowConfirmDelete(false);
      setItemToDelete(null);
      setDeleteBase('');
      setCurrentSubmissionId(null);
      setShowFileModal(false);
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const openDeleteConfirm = (id, base) => {
    setItemToDelete(id);
    setDeleteBase(base);
    setShowConfirmDelete(true);
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' || page === 'instructors' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students' || page === 'instructors') payload.role = page === 'instructors' ? 'instructor' : 'student';

    if ((page === 'announcements' || page === 'assignments') && !payload.courseid) {
      alert('Please select a valid course.');
      return;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Invalid data'));
    }
  };

  const getStudentName = (studentId) => {
    const student = allUsers.find(u => u.id === studentId);
    return student ? student.name : `Student ${studentId}`;
  };

  const sendChatMessage = async () => {
    if (!chatInput.trim() || chatLoading) return;

    const userMessage = chatInput.trim();
    setChatMessages(prev => [...prev, { sender: 'user', text: userMessage }]);
    setChatInput('');
    setChatLoading(true);

    try {
      const res = await axios.post(`${API}/chat`, { message: userMessage });
      setChatMessages(prev => [...prev, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { sender: 'bot', text: 'Sorry, I couldn\'t respond. Try again later.' }]);
    } finally {
      setChatLoading(false);
    }
  };

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  return (
    <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', fontFamily: '"Segoe UI", Roboto, sans-serif', color: '#333' }}>
      {/* Login Page */}
      {page === 'login' && !user && (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', padding: '20px' }}>
          <div style={{ background: 'white', padding: '40px 50px', borderRadius: '16px', boxShadow: '0 20px 40px rgba(0,0,0,0.2)', width: '100%', maxWidth: '420px', textAlign: 'center' }}>
            <h1 style={{ margin: '0 0 30px', color: '#4a5568', fontSize: '2.5rem', fontWeight: '700' }}>NM Student Portal</h1>
            <form onSubmit={login}>
              <input
                type="email"
                placeholder="Enter your email"
                value={emailInput}
                onChange={(e) => setEmailInput(e.target.value)}
                required
                style={{ width: '100%', padding: '14px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
              />
              <button type="submit" style={{ width: '100%', padding: '14px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', fontSize: '1.1rem', fontWeight: '600', cursor: 'pointer', marginTop: '10px' }}>
                Login
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Main App */}
      {user && (
        <>
          <header style={{ background: 'rgba(255,255,255,0.95)', backdropFilter: 'blur(10px)', padding: '15px 30px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)', position: 'sticky', top: 0, zIndex: 1000 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', maxWidth: '1400px', margin: '0 auto' }}>
              <h1 style={{ margin: 0, color: '#4a5568', fontSize: '1.8rem' }}>
                NM Student Portal
              </h1>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <span style={{ color: '#718096', fontWeight: '500' }}>
                  Welcome, <strong>{user.name}</strong> ({user.role})
                </span>
                <button onClick={logout} style={{ padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                  Logout
                </button>
              </div>
            </div>
          </header>

          <nav style={{ background: '#4a5568', padding: '15px 30px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }}>
            <div style={{ maxWidth: '1400px', margin: '0 auto', display: 'flex', gap: '15px', flexWrap: 'wrap' }}>
              <button onClick={() => goTo('courses')} style={{ padding: '12px 24px', background: page === 'courses' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                Courses
              </button>
              {user.role === 'student' && (
                <>
                  <button onClick={() => goTo('assignments')} style={{ padding: '12px 24px', background: page === 'assignments' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} style={{ padding: '12px 24px', background: page === 'announcements' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} style={{ padding: '12px 24px', background: page === 'submissions' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    My Submissions
                  </button>
                </>
              )}
              {user.role === 'instructor' && (
                <>
                  <button onClick={() => goTo('assignments')} style={{ padding: '12px 24px', background: page === 'assignments' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Assignments
                  </button>
                  <button onClick={() => goTo('announcements')} style={{ padding: '12px 24px', background: page === 'announcements' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Announcements
                  </button>
                  <button onClick={() => goTo('submissions')} style={{ padding: '12px 24px', background: page === 'submissions' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Grade Submissions
                  </button>
                  <button onClick={() => goTo('students')} style={{ padding: '12px 24px', background: page === 'students' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Students
                  </button>
                </>
              )}
              {user.role === 'admin' && (
                <>
                  <button onClick={() => goTo('courses')} style={{ padding: '12px 24px', background: page === 'courses' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Courses
                  </button>
                  <button onClick={() => goTo('instructors')} style={{ padding: '12px 24px', background: page === 'instructors' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                    Manage Instructors
                  </button>
                </>
              )}
            </div>
          </nav>

          <main style={{ maxWidth: '1400px', margin: '30px auto', padding: '0 20px' }}>
            <div style={{ background: 'white', borderRadius: '16px', boxShadow: '0 10px 30px rgba(0,0,0,0.1)', padding: '30px', minHeight: '600px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
                <h2 style={{ margin: 0, color: '#2d3748', fontSize: '2rem' }}>
                  {page.charAt(0).toUpperCase() + page.slice(1)}
                </h2>
                {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
                  <button onClick={startAdd} style={{ padding: '12px 24px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '1rem' }}>
                    + Add New {page.slice(0, -1)}
                  </button>
                )}
                {user.role === 'admin' && page === 'instructors' && (
                  <button onClick={startAdd} style={{ padding: '12px 24px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '1rem' }}>
                    + Add Instructor
                  </button>
                )}
              </div>

              {loading && <p style={{ textAlign: 'center', color: '#718096', fontSize: '1.2rem' }}>Loading...</p>}
              {!loading && data.length === 0 && page !== 'courses' && (
                <p style={{ textAlign: 'center', color: '#718096', fontSize: '1.2rem' }}>
                  No {page} available.
                </p>
              )}

              {data.length > 0 && (
                <div style={{ overflowX: 'auto' }}>
                  <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
                    <thead>
                      <tr style={{ background: '#f7fafc', borderBottom: '3px solid #e2e8f0' }}>
                        <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>ID</th>
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Title</th>}
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Description</th>}
                        {page === 'courses' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Syllabus</th>}
                        {page === 'courses' && user.role === 'instructor' && <th style={{ padding: '16px', textAlign: 'left', color: '#4a5568', fontWeight: '600' }}>Enrolled</th>}
